<?php
/**
 * Plugin Name: Reinforce Lab Redirects (A4)
 * Description: Applies the approved redirect map (D-181) from core/reinforce-redirects-map.php, which is generated by claude/tools/redirects.py from claude/data/redirect-map-draft.csv. 301s apply first, before WordPress's own canonical redirect, and go straight to the final page (one hop). 410s apply only when WordPress would otherwise answer 404, so a removal can never hide a page that exists; the visitor sees the normal not-found page with status 410. Query strings (for example ?add-to-cart=) are dropped on redirect. Author archives and /paged-N/ junk are handled in blog/reinforce-blog.php.
 */
if (!defined('ABSPATH')) exit;

require_once __DIR__ . '/reinforce-redirects-map.php';

function rl_redirect_path() {
    $uri = isset($_SERVER['REQUEST_URI']) ? (string) $_SERVER['REQUEST_URI'] : '/';
    $path = rawurldecode((string) parse_url($uri, PHP_URL_PATH));
    $path = '/' . ltrim(preg_replace('#/+#', '/', $path), '/');
    // pages end with a slash; files (with an extension) do not
    if (substr($path, -1) !== '/' && !preg_match('#\.[a-z0-9]{2,5}$#i', $path)) $path .= '/';
    return strtolower($path);
}

add_action('template_redirect', function () {
    if (is_admin() || wp_doing_ajax() || (defined('REST_REQUEST') && REST_REQUEST)) return;
    $rules = rl_redirect_rules();
    $path = rl_redirect_path();
    if (isset($rules['301'][$path])) {
        $t = $rules['301'][$path];
        $to = preg_match('#^https?://#', $t) ? $t : home_url($t);
        wp_safe_redirect($to, 301, 'Reinforce Lab redirects');
        exit;
    }
    if (is_404() && isset($rules['410'][$path])) {
        status_header(410);
        nocache_headers();
        // the normal not-found template, with status 410 Gone
    }
}, 1);
